using Microsoft.EntityFrameworkCore;

public class Game
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string Platform { get; set; } = "";
}

public class Review
{
    public int Id { get; set; }
    public int GameId { get; set; }
    public string Reviewer { get; set; } = "";
    public int Rating { get; set; }
}

// One row of the catalog.
public record GameSummary(
    int Id, string Title, string Platform,
    int Reviews, double Rating);

public class PierDb(DbContextOptions<PierDb> options)
    : DbContext(options)
{
    public DbSet<Game> Games => Set<Game>();
    public DbSet<Review> Reviews => Set<Review>();

    protected override void OnModelCreating(ModelBuilder model)
    {
        model.Entity<Game>().HasData(
            G(1, "Star Garden", "switch"),
            G(2, "Byte Racers", "pc"),
            G(3, "Robo Rumble", "pc"),
            G(4, "Moon Quest", "switch"),
            G(5, "Puzzle Pond", "switch"));
        model.Entity<Review>().HasData(
            R(1, 1, "Pip", 5),
            R(2, 1, "Mossy", 4),
            R(3, 2, "Pip", 3),
            R(4, 3, "Fern", 4),
            R(5, 3, "Otto", 3),
            R(6, 4, "Ivy", 3),
            R(7, 4, "Pip", 4));
    }

    static Game G(int id, string title, string platform) =>
        new() { Id = id, Title = title, Platform = platform };

    static Review R(int id, int game, string who, int rating) =>
        new()
        {
            Id = id, GameId = game,
            Reviewer = who, Rating = rating,
        };
}

