import { useEffect, useState } from "react";
import CatalogTable from "./CatalogTable.jsx";

// "dreamcast" isn't a shelf here: it's there to
// see what the page does when the API says no.
const PLATFORMS = ["all", "switch", "pc", "dreamcast"];

export default function App() {
  const [platform, setPlatform] = useState("all");
  const [rows, setRows] = useState(null);
  const [error, setError] = useState(null);

  useEffect(() => {
    const query =
      platform === "all" ? "" : `?platform=${platform}`;
    setError(null);
    fetch(`/api/games${query}`)
      .then(async (response) => {
        const data = await response.json();
        if (response.ok) {
          setRows(data);
        } else {
          setError(data.title);
          setRows([]);
        }
      });
  }, [platform]);

  return (
    <main>
      <h1>Pixel Pier</h1>
      <nav aria-label="Platforms">
        {PLATFORMS.map((p) => (
          <button
            key={p}
            id={`show-${p}`}
            aria-pressed={p === platform}
            onClick={() => setPlatform(p)}
          >
            {p}
          </button>
        ))}
      </nav>
      {error && (
        <p id="error" role="alert">
          {error}
        </p>
      )}
      {rows === null ? (
        <p>Loading games…</p>
      ) : (
        <CatalogTable rows={rows} />
      )}
    </main>
  );
}

