using Microsoft.EntityFrameworkCore;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddDbContext<PierDb>(
    o => o.UseInMemoryDatabase("pier"));
var app = builder.Build();

// Creates the database with its seed rows.
using (var scope = app.Services.CreateScope())
{
    scope.ServiceProvider.GetRequiredService<PierDb>()
        .Database.EnsureCreated();
}

// GET /api/games?platform=switch (or pc).
// Other platforms: 400, with problem details.
app.MapGet("/api/games", (string platform, PierDb db) =>
{
    if (platform is not null && platform is not ("switch" or "pc"))
        return Results.Problem(
            title: $"There's no {platform} shelf.",
            statusCode: 400);

    var games = db.Games
        .Where(g => platform == null || g.Platform == platform)
        .ToList();
    var reviews = db.Reviews.ToList();
    var catalog = games
        .Select(g => new GameSummary(
            g.Id, g.Title, g.Platform,
            reviews.Count(r => r.GameId == g.Id),
            Rating(reviews, g.Id)))
        .OrderByDescending(s => s.Rating)
        .ThenBy(s => s.Title)
        .ToList();
    return Results.Ok(catalog);
});

app.MapPost("/api/reviews", (NewReview input, PierDb db) =>
{
    var errors = new Dictionary<string, string[]>();
    if (db.Games.Find(input.GameId) is null)
        errors["gameId"] = [$"There's no game {input.GameId}."];
    if (string.IsNullOrWhiteSpace(input.Reviewer))
        errors["reviewer"] = ["Write your name."];
    if (input.Rating is < 1 or > 5)
        errors["rating"] = ["A rating is 1 to 5."];
    if (errors.Count > 0) return Results.ValidationProblem(errors);

    var review = new Review
    {
        GameId = input.GameId,
        Reviewer = input.Reviewer.Trim(),
        Rating = input.Rating,
    };
    db.Reviews.Add(review);
    db.SaveChanges();
    return Results.Created($"/api/reviews/{review.Id}", review);
});

app.MapGet("/api/reviews/{id:int}", (int id, PierDb db) =>
    db.Reviews.Find(id) is { } review
        ? Results.Ok(review)
        : Results.NotFound());

app.MapDelete("/api/reviews/{id:int}", (int id, PierDb db) =>
{
    if (db.Reviews.Find(id) is not { } review)
        return Results.NotFound();
    db.Reviews.Remove(review);
    db.SaveChanges();
    return Results.NoContent();
});

app.Run();

// A game's average rating, to 1 decimal place.
// No reviews yet? Then 0.
static double Rating(List<Review> reviews, int game)
{
    var mine = reviews.Where(r => r.GameId == game).ToList();
    if (mine.Count == 0) return 0;
    return Math.Round(mine.Average(r => r.Rating), 1);
}

