record Stamp(int Id, string Owner, string Picture);
", "api/StampEndpoints.cs": "static class StampEndpoints
{
    // Endpoints can live in their own file: an
    // extension method that Program.cs calls.
    public static void MapStampEndpoints(
        this WebApplication app, List<Stamp> stamps)
    {
        // Only the owner's stamps, never everyone's.
        app.MapGet("/api/stamps", (string owner) =>
            stamps.Where(s => s.Owner == owner));

        // The same stamp twice is a 409 Conflict.
        app.MapPost("/api/stamps", (Stamp input) =>
        {
            if (stamps.Any(s => s.Owner == input.Owner
                && s.Picture == input.Picture))
                return Results.Problem(
                    title: "You have that stamp already.",
                    statusCode: 409);
            var stamp = input with { Id = stamps.Count + 1 };
            stamps.Add(stamp);
            return Results.Created(
                $"/api/stamps/{stamp.Id}", stamp);
        });
    }
}
