import { useEffect, useState } from "react";

const EMPTY = { gameId: "", reviewer: "", rating: "" };

export default function ReviewForm({ onReviewed }) {
  const [games, setGames] = useState([]);
  const [form, setForm] = useState(EMPTY);
  const [errors, setErrors] = useState({});

  useEffect(() => {
    fetch("/api/games/titles")
      .then((response) => response.json())
      .then((data) => setGames(data));
  }, []);

  function update(field, value) {
    setForm({ ...form, [field]: value });
  }

  async function handleSubmit(event) {
    event.preventDefault();
    const response = await fetch("/api/reviews", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        gameId: Number(form.gameId),
        reviewer: form.reviewer,
        rating: Number(form.rating),
      }),
    });
    if (response.ok) {
      setForm(EMPTY);
      setErrors({});
      onReviewed();
    } else {
      const problem = await response.json();
      setErrors(problem.errors ?? {});
    }
  }

  return (
    <form id="review-form" onSubmit={handleSubmit} noValidate>
      <h2>Review a game</h2>
      <Field id="game" label="Game" error={errors.gameId?.[0]}>
        {(props) => (
          <select {...props} value={form.gameId}
            onChange={(e) => update("gameId", e.target.value)}>
            <option value="">Choose a game</option>
            {games.map((g) => (
              <option key={g.id} value={g.id}>
                {g.title}
              </option>
            ))}
          </select>
        )}
      </Field>
      <Field id="reviewer" label="Your name"
        error={errors.reviewer?.[0]}>
        {(props) => (
          <input {...props} value={form.reviewer}
            onChange={(e) => update("reviewer", e.target.value)} />
        )}
      </Field>
      <Field id="rating" label="Rating (1 to 5)"
        error={errors.rating?.[0]}>
        {(props) => (
          <input {...props} type="number" value={form.rating}
            onChange={(e) => update("rating", e.target.value)} />
        )}
      </Field>
      <button type="submit">Post review</button>
    </form>
  );
}

// A label, its control, and the API's message.
// The control gets aria-invalid and
// aria-describedby, so a screen reader reads
// the message with it.
function Field({ id, label, error, children }) {
  const errorId = `${id}-error`;
  return (
    <div className="field">
      <label htmlFor={id}>{label}</label>
      {children({
        id,
        "aria-invalid": error ? "true" : undefined,
        "aria-describedby": error ? errorId : undefined,
      })}
      {error && (
        <p id={errorId} className="field-error">
          {error}
        </p>
      )}
    </div>
  );
}

