import { useEffect, useState } from "react";

// Codegrove has no sign-in, so the page shows
// Pip's wishlist. A real app would use the
// signed-in player.
const PLAYER = "Pip";

export default function Wishlist() {
  const [games, setGames] = useState([]);
  const [wishes, setWishes] = useState([]);
  const [gameId, setGameId] = useState("");
  const [error, setError] = useState(null);

  useEffect(() => {
    fetch("/api/games/titles")
      .then((response) => response.json())
      .then((data) => setGames(data));
  }, []);

  function load() {
    fetch(`/api/wishlist?player=${PLAYER}`)
      .then((response) => response.json())
      .then((data) => setWishes(data));
  }

  useEffect(() => {
    load();
  }, []);

  async function add() {
    const response = await fetch("/api/wishlist", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        player: PLAYER,
        gameId: Number(gameId),
      }),
    });
    if (response.ok) {
      setError(null);
      load();
    } else {
      setError((await response.json()).title);
    }
  }

  async function remove(id) {
    await fetch(`/api/wishlist/${id}`, { method: "DELETE" });
    load();
  }

  return (
    <section aria-labelledby="wish-title">
      <h2 id="wish-title">{PLAYER}'s wishlist</h2>
      <ul id="wishlist">
        {wishes.map((w) => (
          <li key={w.id}>
            <span>{w.title}</span>
            <button
              onClick={() => remove(w.id)}
              aria-label={`Remove ${w.title}`}
            >
              Remove
            </button>
          </li>
        ))}
      </ul>
      <label htmlFor="wish-game">Add a game</label>
      <select
        id="wish-game"
        value={gameId}
        onChange={(e) => setGameId(e.target.value)}
      >
        <option value="">Choose a game</option>
        {games.map((g) => (
          <option key={g.id} value={g.id}>
            {g.title}
          </option>
        ))}
      </select>
      <button id="wish-add" onClick={add}>
        Add to wishlist
      </button>
      {error && (
        <p id="wish-error" role="alert">
          {error}
        </p>
      )}
    </section>
  );
}

