public static class WishlistEndpoints
{
    public static void MapWishlist(this WebApplication app)
    {
        // GET /api/wishlist?player=Pip: one
        // player's wishes, A to Z by title.
        app.MapGet("/api/wishlist",
            (string player, PierDb db) =>
        {
            if (string.IsNullOrWhiteSpace(player))
            {
                var errors = new Dictionary<string, string[]>
                {
                    ["player"] = ["Say whose wishlist to show."],
                };
                return Results.ValidationProblem(errors);
            }

            var wishes =
                from w in db.Wishlist
                where w.Player == player
                join g in db.Games on w.GameId equals g.Id
                orderby g.Title
                select new Wish(w.Id, g.Id, g.Title);
            return Results.Ok(wishes.ToList());
        });

        app.MapPost("/api/wishlist",
            (NewWish input, PierDb db) =>
        {
            var game = db.Games.Find(input.GameId);
            var errors = new Dictionary<string, string[]>();
            if (string.IsNullOrWhiteSpace(input.Player))
                errors["player"] = ["Say whose wishlist."];
            if (game is null)
                errors["gameId"] =
                    [$"There's no game {input.GameId}."];
            if (errors.Count > 0)
                return Results.ValidationProblem(errors);

            var already = db.Wishlist.Any(w =>
                w.Player == input.Player && w.GameId == game.Id);
            if (already)
                return Results.Problem(
                    title: "That game is already on your wishlist.",
                    statusCode: 409);

            var item = new WishlistItem
            {
                Player = input.Player,
                GameId = game.Id,
            };
            db.Wishlist.Add(item);
            db.SaveChanges();
            return Results.Created($"/api/wishlist/{item.Id}",
                new Wish(item.Id, game.Id, game.Title));
        });

        app.MapDelete("/api/wishlist/{id:int}",
            (int id, PierDb db) =>
        {
            if (db.Wishlist.Find(id) is not { } item)
                return Results.NotFound();
            db.Wishlist.Remove(item);
            db.SaveChanges();
            return Results.NoContent();
        });
    }
}

